package com.hms.dao.impl;
import com.hms.config.DatabaseConnection; import com.hms.dao.AppointmentDao; import com.hms.model.Appointment; import java.sql.*; import java.time.*; import java.util.ArrayList; import java.util.List;
public class AppointmentDaoImpl implements AppointmentDao { private Appointment map(ResultSet r)throws SQLException{return new Appointment(r.getInt("appointment_id"),r.getInt("patient_id"),r.getString("patient_name"),r.getInt("doctor_id"),r.getString("doctor_name"),r.getDate("appointment_date").toLocalDate(),r.getTime("appointment_time").toLocalTime(),r.getString("reason"),r.getString("status"),r.getString("notes"));}
 public List<Appointment> findAll(String status,LocalDate from)throws SQLException{List<Appointment> out=new ArrayList<>();String q="SELECT a.*,p.full_name patient_name,d.full_name doctor_name FROM appointments a JOIN patients p ON p.patient_id=a.patient_id JOIN doctors d ON d.doctor_id=a.doctor_id WHERE (?='ALL' OR a.status=?) AND (? IS NULL OR a.appointment_date>=?) ORDER BY a.appointment_date,a.appointment_time";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setString(1,status);p.setString(2,status);if(from==null){p.setNull(3,Types.DATE);p.setNull(4,Types.DATE);}else{p.setDate(3,Date.valueOf(from));p.setDate(4,Date.valueOf(from));}try(ResultSet r=p.executeQuery()){while(r.next())out.add(map(r));}}return out;}
 public Appointment save(Appointment a)throws SQLException{String q="INSERT INTO appointments(patient_id,doctor_id,appointment_date,appointment_time,reason,status,notes) VALUES(?,?,?,?,?,?,?)";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(q,Statement.RETURN_GENERATED_KEYS)){p.setInt(1,a.patientId());p.setInt(2,a.doctorId());p.setDate(3,Date.valueOf(a.appointmentDate()));p.setTime(4,Time.valueOf(a.appointmentTime()));p.setString(5,a.reason());p.setString(6,a.status());p.setString(7,a.notes());p.executeUpdate();try(ResultSet k=p.getGeneratedKeys()){int id=k.next()?k.getInt(1):0;return new Appointment(id,a.patientId(),a.patientName(),a.doctorId(),a.doctorName(),a.appointmentDate(),a.appointmentTime(),a.reason(),a.status(),a.notes());}}}
 public void reschedule(int id, java.time.LocalDate date, java.time.LocalTime time)throws SQLException{try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE appointments SET appointment_date=?, appointment_time=?, status='Scheduled' WHERE appointment_id=?")){p.setDate(1,Date.valueOf(date));p.setTime(2,Time.valueOf(time));p.setInt(3,id);p.executeUpdate();}}
 public void updateStatus(int id,String status)throws SQLException{try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE appointments SET status=? WHERE appointment_id=?")){p.setString(1,status);p.setInt(2,id);p.executeUpdate();}}
 public void delete(int id)throws SQLException{try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM appointments WHERE appointment_id=?")){p.setInt(1,id);p.executeUpdate();}}
}
